factories['./native-steering.cjs']=(module,exports,require)=>{
// Complete runAnalogSteering (0x24854) and runDigitalSteering (0x24964).
// Inputs are the two native control values; outputs are player offsets 0x38/0x3c.
function analogSteering(state){
 const f=Math.fround;
 function response(value){
  const square=f(value*value),cube=f(value*square),fourth=f(value*cube);
  return f(fourth*20*(value>0?1:-1));
 }
 state.left=Math.max(-1,Math.min(1,f(state.left)));
 state.right=Math.max(-1,Math.min(1,f(state.right)));
 state.leftTrack=response(state.left);state.rightTrack=response(state.right);
 return state;
}
function digitalSteering(state){
 if(state.ready!==1){state.leftTrack=0;state.rightTrack=0;return state;}
 const threshold=Math.fround(.4);
 function response(value,previous){
  if(value>=0&&value<threshold||value<0&&value>-threshold)return 0;
  if(value>0)return 20;
  if(value<0)return -20;
  return previous;
 }
 state.leftTrack=response(Math.fround(state.left),state.leftTrack);
 state.rightTrack=response(Math.fround(state.right),state.rightTrack);
 return state;
}
module.exports={analogSteering,digitalSteering};

};
