 const centerX=tank.v.reduce((sum,v)=>sum+v[0],0)/tank.v.length,centerZ=tank.v.reduce((sum,v)=>sum+v[2],0)/tank.v.length;
 const glyphScale=38/Math.max(...tank.v.map(v=>Math.hypot(v[0]-centerX,v[2]-centerZ)));
