// Native line and particle triangle lists share the drawGame flush.
const nativePolyPresenter=PLAYER_CORE.createNativePolyPresenter(NATIVE_ENEMY_STATE);
function createNativeVectorQueue(w,h){const queue=[];queue.viewWidth=w;queue.viewHeight=h;queue.coreCoordinates=0;queue.coreColors=0;queue.polyCoordinates=0;queue.polyColors=0;queue.triangles=[];return queue;}
function flushNativeVectors(queue){drawNativeVectors(queue.viewWidth,queue.viewHeight,queue);queue.length=0;queue.coreCoordinates=0;queue.coreColors=0;queue.polyCoordinates=0;queue.polyColors=0;queue.triangles.length=0;}
function queueNativeVector(queue,a,b,color,depthA,depthB){
 // vlAddVector 0x9984..0x99bc flushes before this submission when full.
 if(queue.coreCoordinates>=988||queue.coreColors>1987)flushNativeVectors(queue);
 const settings=preferenceStore.state.settings,colors=PLAYER_CORE.nativeVectorColors(color,depthA,depthB,settings.brightness,settings.glowEnable,renderFlash);
 if(colors.core||colors.glow)queue.push({a,b,...colors});
 if(colors.core){queue.coreCoordinates=(queue.coreCoordinates||0)+6;queue.coreColors=(queue.coreColors||0)+8;}
}
function queueNativePolyVector(queue,vertices){
 // vlAddPolyVector 0xabc4..0xabfc checks its own shared-batch capacity.
 if(queue.polyCoordinates>=988||queue.polyColors>1987)flushNativeVectors(queue);
 queue.triangles.push(...vertices);queue.polyCoordinates+=vertices.length*2;queue.polyColors+=vertices.length*4;
}
function drawNativeVectors(w,h,queue){
 const scale=Math.min(w/800,h/600),screen=v=>[w/2+(v[1]+session.centerX-400)*scale,h/2-(v[0]+session.centerY-300)*scale];
 ctx.save();ctx.beginPath();ctx.rect(w/2-400*scale,h/2-300*scale,800*scale,600*scale);ctx.clip();ctx.globalCompositeOperation='source-over';ctx.globalAlpha=1;
 ctx.save();for(const pass of ['glow','core']){ctx.lineWidth=(pass==='glow'?8:preferenceStore.state.settings.lineRadius)*scale;
  for(const vector of queue){const color=vector[pass];if(!color)continue;ctx.strokeStyle='rgba('+[...color.slice(0,3),color[3]/255].join(',')+')';ctx.beginPath();ctx.moveTo(...screen(vector.a.map(Math.fround)));ctx.lineTo(...screen(vector.b.map(Math.fround)));ctx.stroke();}}
 ctx.restore();
 // Original 0x98a8..0x98f4 submits particle triangles after both line passes.
 const polyScreen=p=>[w/2+(p[1]-400)*scale,h/2-(p[0]-300)*scale];
 for(let i=0;i<queue.triangles.length;i+=3){
  const vertices=queue.triangles.slice(i,i+3).map(v=>({point:polyScreen(v.point),color:v.color})),gradient=PLAYER_CORE.nativeTriangleAlphaGradient(vertices);if(!gradient)continue;
  const rgba=a=>'rgba('+[...gradient.rgb,a].join(',')+')';
  if(gradient.constant!==undefined)ctx.fillStyle=rgba(gradient.constant);
  else{const fill=ctx.createLinearGradient(...gradient.from,...gradient.to);fill.addColorStop(0,rgba(gradient.low));fill.addColorStop(1,rgba(gradient.high));ctx.fillStyle=fill;}
  ctx.beginPath();ctx.moveTo(...vertices[0].point);ctx.lineTo(...vertices[1].point);ctx.lineTo(...vertices[2].point);ctx.closePath();ctx.fill();
 }
 ctx.restore();
}
// Canvas presentation adapter. Geometry, palettes, projection and line gates are native.
function drawNativeScene(w,h,sharedQueue){
 const core=PLAYER_CORE, brightness=preferenceStore.state.settings.brightness, camera=core.cameraMatrix(player,{inGame:session.inGame,life:session.life,startHeight:session.startHeight,destroyedCameraAngle:session.destroyedCameraAngle}),scale=Math.min(w/800,h/600);
 const screen=v=>[w/2+(v[1]+session.centerX-400)*scale,h/2-(v[0]+session.centerY-300)*scale],wireQueue=sharedQueue||createNativeVectorQueue(w,h);
 ctx.save();ctx.beginPath();ctx.rect(w/2-400*scale,h/2-300*scale,800*scale,600*scale);ctx.clip();
 const backgroundState={life:session.life,destroyedCameraAngle:session.destroyedCameraAngle??0};
 for(const quad of starQuads){
  const [r,g,b,a]=quad.color;ctx.fillStyle='rgba('+[r,g,b,a/255].join(',')+')';ctx.beginPath();
  for(const [k,v]of [quad.vertices[0],quad.vertices[1],quad.vertices[3],quad.vertices[2]].entries()){const p=screen(v);k?ctx.lineTo(...p):ctx.moveTo(...p);}ctx.closePath();ctx.fill();
 }
 // Native drawBackground renders the moon before the mountain vectors.
 drawObject(NATIVE_BACKGROUND.moon,NATIVE_BACKGROUND.moon.position,NATIVE_BACKGROUND.moon.rotation,{camera:core.backgroundCamera(player,backgroundState),distance:0});
 // Native drawBackground emits mountain vectors before world objects.
 const mountainState={life:session.life,destroyedCameraAngle:session.destroyedCameraAngle??0};
 const degrees=Math.fround(Math.fround(player.heading)*57.2957795786);
 for(const vector of core.mountainOutline(player,degrees,mountainState,NATIVE_BACKGROUND)){
  queueNativeVector(wireQueue,vector.a,vector.b,vector.color,0,0);
 }
 function drawObject(part,position,rotation,options={}){
  const visibility=options.camera||options.terrain?{visible:true,distance:options.distance}:core.nativeObjectVisibility(player,position);if(!visibility.visible)return;
  const object=core.objectMatrix({...part,position,rotation}),matrix=core.multiplyMatrix(object,options.camera||camera);
  const projected=part.v.map(v=>core.projectVertex(core.transformVertex(matrix,v)));
  const [fillAlpha,fr,fg,fb]=part.fill;let alpha=fillAlpha;
  // Native object-list fill gate; the separately drawn moon retains its own path.
  if(!options.terrain&&(options.camera||core.nativeShouldDrawFill(visibility.distance,preferenceStore.state.settings.renderFills))&&alpha>0&&(fr||fg||fb))for(const polygon of part.p){
   if(alpha<=0)break;
   if(polygon.length<3||polygon.some(i=>projected[i][2]<.001))continue;
   alpha=core.nativeFillAlpha(alpha,polygon.map(i=>projected[i][2]));if(alpha<=0)continue;
   ctx.fillStyle='rgba('+[fr*255,fg*255,fb*255,Math.min(1,alpha)].join(',')+')';ctx.beginPath();
   polygon.forEach((index,k)=>{const p=screen(projected[index].map(Math.fround));k?ctx.lineTo(...p):ctx.moveTo(...p);});ctx.closePath();ctx.fill();
  }
  const [sourceAlpha,r,g,blue]=part.line;if(!(sourceAlpha>0)||!(r||g||blue))return;
  ctx.lineWidth=scale;
  for(const [a,b]of part.lines)if(core.nativeWireVisible(projected[a],projected[b])){
   queueNativeVector(wireQueue,projected[a],projected[b],part.line,projected[a][2],projected[b][2]);
  }
 }
 function vehicle(model,x,z,rotation){
  const bodyY=model.parts[0].position[0];
  for(const part of model.parts)if(part.active)drawObject(part,[bodyY,x,z],rotation);
 }
 function rawObject(record,geometry){const part=WEAPON_WORLD.objectPart(record,geometry);if(part.active)drawObject(part,part.position,part.rotation);}
 if(droneTest.checked){
  for(const k of enemyWorld.visibleTerrain()){const part=WEAPON_WORLD.objectPart(enemyWorld.terrain[k],NATIVE_WORLD_STATE.terrain[k].geometry);drawObject(part,part.position,part.rotation,{terrain:true,distance:0});}
 }
 // drawGame 0x2d18c..0x2d1b8: ground effects and obstacles precede pickups.
 for(let k=0;k<enemyWorld.ground.length;k++)rawObject(enemyWorld.ground[k],enemyWorld.groundGeometry[k]);
 if(droneTest.checked)for(let k=0;k<40;k++)rawObject(enemyWorld.obstacles[k],enemyWorld.obstacleGeometry[k]);
 // drawGame 0x2d1bc..0x2d290: pickups/rings precede vehicle groups.
 for(let k=0;k<65;k++)rawObject(weaponWorld.powerups[k],NATIVE_POWERUPS.entries[k].part);
 for(const k of PLAYER_CORE.nativeDrawListIndices(weaponWorld.rings,true))rawObject(weaponWorld.rings[k],NATIVE_WEAPON_POOLS.rings[k].part);
 for(const k of PLAYER_CORE.nativeDrawListIndices(enemyWorld.trailRecords,true))rawObject(enemyWorld.trailRecords[k],NATIVE_TRAIL_POOL.objects[k].geometry); // drawGame 0x2d1fc
 for(let k=0;k<enemyWorld.shrapnelRecords.length;k++)rawObject(enemyWorld.shrapnelRecords[k],NATIVE_SHRAPNEL_POOL.objects[k].geometry); // drawGame 0x2d21c
 if(targetTest.checked&&!droneTest.checked)for(const target of labTargets)if(target.life===1)vehicle(NATIVE_VEHICLES.vehicles.Tank1,target.x,target.z,[0,0,0]);
 if(droneTest.checked&&!session.attractLogo)for(const [i,v]of enemyWorld.vehicles.entries()){
  const frame=lightningFrames[i],mode=frame?.mode??core.nativeVehicleDrawMode(v.view,session.attractLogo);
  if(mode==='standard')for(let k=0;k<v.objects.length;k++){if(!new DataView(v.objects[k].buffer,v.objects[k].byteOffset,v.objects[k].byteLength).getInt8(0x190))break;rawObject(v.objects[k],NATIVE_VEHICLES.vehicles[v.name].parts[k]);}
  for(const vector of frame?.commands||[])queueNativeVector(wireQueue,vector.a,vector.b,vector.color,vector.a[2],vector.b[2]);
 }
 // Native drawGame 0x2d35c/0x2d364: particles follow vehicle groups.
 for(const vector of effectVectors){if(vector.address==='0xabb0')queueNativePolyVector(wireQueue,vector.triangles);else queueNativeVector(wireQueue,vector.a,vector.b,vector.color,vector.a[2],vector.b[2]);}
 // drawGame 0x2d804..0x2d844: enemy round lists precede the player's list.
 function projectile(round,model){if(round.active)drawObject(model.part,[round.y,round.x,round.z],[round.yaw,round.pitch,round.roll]);}
 // Original Screamer cubes/trails precede enemy and player cannon lists.
 for(let k=0;k<20;k++){
  const object=weaponWorld.screamerObjects[k];if(!new DataView(object.buffer,object.byteOffset,object.byteLength).getInt8(0x190))continue;
  rawObject(object,NATIVE_WEAPON_POOLS.screamers[k].part);
  for(const vector of core.screamerTrail(weaponWorld.screamerRecords[k])){
   const a=core.projectVertex(core.transformVertex(camera,vector.a)),b=core.projectVertex(core.transformVertex(camera,vector.b));
   if(core.nativeSceneLineVisible(a,b))queueNativeVector(wireQueue,a,b,vector.color,0,0);
  }
 }
 if(droneTest.checked)for(const item of enemyWorld.activeRounds())rawObject(item.record,NATIVE_ENEMY_MESHES.models[String(item.vehicle.kind)]);
 for(let k=0;k<20;k++)rawObject(weaponWorld.roundBytes[k],NATIVE_WEAPON_POOLS.rounds[k].part);
 ctx.restore();
 if(!sharedQueue)flushNativeVectors(wireQueue);
}

// Native background randomness runs once per simulation frame, independent of display cadence/view.
function finishNativeFrame(){
 session.simulationTicks++;
 PLAYER_CORE.runShake(session,rng);
 playNativeDestructionEvents(enemyWorld.listenerAudio(player,session,weaponWorld,rng));
 enemyWorld.shootingStars(player,session,weaponWorld,rng); // original drawBackground precedes star quad RNG
 starQuads=PLAYER_CORE.starfield(stars,player,{life:session.life,destroyedCameraAngle:session.destroyedCameraAngle??0},rng,preferenceStore.state.settings.brightness);
 renderFlash=session.flashScreen;
 const camera=PLAYER_CORE.cameraMatrix(player,{inGame:session.inGame,life:session.life,startHeight:session.startHeight,destroyedCameraAngle:session.destroyedCameraAngle});
 lightningFrames=droneTest.checked?PLAYER_CORE.nativeLightningFrame({vehicles:enemyWorld.vehicles,models:NATIVE_VEHICLES.vehicles,player,state:session,camera,rng,objectPart:WEAPON_WORLD.objectPart}):[];
 effectVectors=enemyWorld.drawEffects(camera,rng).map(vector=>vector.address==='0xabb0'?{...vector,triangles:nativePolyPresenter(vector.a,vector.b,vector.color,{centerY:session.centerY,centerX:session.centerX,brightness:preferenceStore.state.settings.brightness,flash:renderFlash})}:vector);
 updateNativeHud();
}

function updateNativeHud(){
 const enemies=labEnemies().map((enemy,k)=>({...enemy,rounds:droneTest.checked?enemyWorld.vehicles[k].rounds.map((b,j)=>enemyWorld.vehicles[k].roundViews[j].getInt8(0x190)?WEAPON_WORLD.readRound(b):{active:false}):[]}));
 const state={...session,...weapons,clockSeconds:session.simulationTicks*NATIVE_FRAME_SECONDS,rawLeft:Math.fround(160+player.left*160),rawRight:Math.fround(160+player.right*160)};
 hudFrame=hudMachine.hud(player,state,{enemies,objects:droneTest.checked?enemyWorld.obstacleStates():[],screamerRecords:weaponWorld.screamerRecords,screamerObjects:weaponWorld.screamerObjects},rng).map(prepareNativeBitmap);
 weapons.unavailableTimer=hudMachine.state().unavailableTimer;
 Object.assign(session,hudMachine.feedback());
}
function prepareNativeBitmap(command){
  if(!command.texture)return command;
  // Sprite::Draw (0xcdf8..0xcf04): native alternating 0.92 modulation,
  // byte color quantization and 0.35-pixel Y offset, once per native frame.
  const old=hudSpritePhases.get(command.texture)||false,next=!old;hudSpritePhases.set(command.texture,next);
  const alpha=Math.fround(old?command.alpha*.92:command.alpha),byte=Math.trunc(Math.fround(alpha*255))&255;
  return {...command,presentationAlpha:byte/255,jitterY:next?Math.fround(.35):0};
}
function drawNativeFrameBitmaps(w,h){
 const scale=Math.min(w/800,h/600),left=w/2-400*scale,top=h/2-300*scale;ctx.save();
 for(const command of frameBitmaps){const image=hudImages.get(NATIVE_HUD_TEXTURES[command.texture]);if(!image?.complete||!image.naturalWidth)continue;ctx.globalCompositeOperation=command.blend?'source-over':'lighter';ctx.globalAlpha=command.presentationAlpha;ctx.drawImage(image,left+command.x*scale,top+(600-command.y-command.h-command.jitterY)*scale,command.w*scale,command.h*scale);}
 ctx.restore();
}
function onNativeHudEvent(address,state){
 if(address===0x26b48){
  if(droneTest.checked){Object.assign(session,state);playNativeDestructionEvents(enemyWorld.finishGame(player,session,weapons,weaponWorld,rng));releaseControls();audio.endGameplay();return {state:session,player};}
  Object.assign(session,state);const events=PLAYER_CORE.endNativeGame(session,player,{qualifies:preferenceStore.qualifies(session.mode,session.score)});
  runNativeFlowEvents(events);
  releaseControls();audio.endGameplay();enemyWorld.sync(player,session,weaponWorld);return {state:session,player};
 }
 if(enemyWorld.machine.voiceSDK)playNativeDestructionEvents(enemyWorld.sound(address,[],rng));
}

function drawNativeHud(w,h,sharedQueue){
 const wireQueue=sharedQueue||createNativeVectorQueue(w,h);
 const scale=Math.min(w/800,h/600),left=w/2-400*scale,top=h/2-300*scale,screen=v=>[w/2+(v[1]+session.centerX-400)*scale,h/2-(v[0]+session.centerY-300)*scale];
 ctx.save();ctx.beginPath();ctx.rect(left,top,800*scale,600*scale);ctx.clip();
 for(const command of hudFrame){
  if(command.texture){
   const name=NATIVE_HUD_TEXTURES[command.texture],img=hudImages.get(name);if(!img||!img.complete||!img.naturalWidth)continue;
   ctx.globalCompositeOperation=command.blend?'source-over':'lighter';ctx.globalAlpha=command.presentationAlpha;
   ctx.drawImage(img,left+command.x*scale,top+(600-command.y-command.h-command.jitterY)*scale,command.w*scale,command.h*scale);
  }else if(command.polygon){
   const [alpha,r,g,b]=command.color;ctx.globalCompositeOperation='source-over';ctx.globalAlpha=1;ctx.fillStyle='rgba('+[r*255,g*255,b*255,alpha].join(',')+')';ctx.beginPath();command.polygon.forEach((v,k)=>k?ctx.lineTo(...screen(v)):ctx.moveTo(...screen(v)));ctx.closePath();ctx.fill();
  }else if(command.a){
   queueNativeVector(wireQueue,command.a,command.b,command.color,0,0);
  }
 }
 ctx.restore();
 if(!sharedQueue)flushNativeVectors(wireQueue);
}
function positionNativePause(w,h){
 const scale=Math.min(w/800,h/600),width=Math.max(44,50*scale),height=Math.max(44,50*scale);
 const x=canvas.offsetLeft+w/2+(session.centerX-400-5)*scale,y=canvas.offsetTop+h/2-(session.centerY-300+275)*scale;
 // Keep the platform's minimum touch target fully visible around the native icon.
 Object.assign(nativePauseButton.style,{left:Math.max(canvas.offsetLeft,Math.min(canvas.offsetLeft+w-width,x-width/2))+'px',top:Math.max(canvas.offsetTop,Math.min(canvas.offsetTop+h-height,y-height/2))+'px',width:width+'px',height:height+'px'});
}
